import React from "react";

const GigBoardMenu = () => {
  console.log("✅ GigBoardMenu loaded");

  return (
    <div style={{ padding: "2rem", background: "#eee", textAlign: "center" }}>
      <h2>Gig Board Menu</h2>
      <button onClick={() => alert("Browse")}>Browse Gig Board</button>
      <button onClick={() => alert("View My Gigs")}>View My Gigs</button>
      <button onClick={() => alert("Post A New Gig")}>Post A New Gig</button>
      <button onClick={() => alert("Notifications")}>Notifications</button>
    </div>
  );
};

export default GigBoardMenu;
